#!/usr/bin/env python3
"""SUMO reference for a corridor scenario generated by ngsim_corridor_scenario.py (same vehicles, same signals).

Purpose: give a well-known reference model (SUMO Krauss) run on the *identical* initial states, routes, signal programs and
desired speeds as the HTC runs, scored with the *identical* measures (stop-line crossing error against NGSIM, road time),
so the HTC result can be read next to "how close does an established simulator get". It is a reference, not ground truth.

Mapping (everything is read from the generated scenario directory; no new data):
- edges = the layout links in order (road, connector box, road, ...), lengths from links_0.json, 2 lanes, lane j -> lane j;
- signal = fixed-time program from traffic_signals_0.json (green -> GG, yellow -> yy, otherwise rr) on the node that ends the
  approach road; the unsignalised intersection has no signal and no priority conflict (single straight movement);
- vehicle = startTick*0.1 s departure, departPos/departSpeed/departLane from the HTC actor, length = size, Krauss with
  accel = microAcceleration, decel 4.5, emergencyDecel 9, tau 1.0, minGap 2.5 (SUMO defaults except accel), sigma as given,
  desired speed through speedFactor = desired / 25 m/s edge limit (the HTC road limit 13.41 m/s when the vehicle has none);
- arrival position = microArrivalPosition on the last edge;
- SUMO cannot insert a vehicle faster than its own maximum speed, so a departure speed above the vehicle's desired speed is clipped to it; the
  number and size of clippings is recorded in the analysis (`initial_speed_clipped_to_desired`).
"""
import argparse
import hashlib
import json
import math
import statistics
import subprocess
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

FT = .3048
LIMIT = 48.28/3.6          # HTC road limit, used when a vehicle has no desired speed
EDGE_SPEED = 25.0          # SUMO edge limit; the per-vehicle speedFactor sets the desired speed (observed departure speeds exceed 13.41 m/s)


def build(scenario, out, sigma):
    meta = json.loads((scenario/'scenario_metadata.json').read_text())
    data = scenario/'data'
    links = {l['id']: l['data']['content'] for l in json.loads((data/'links_0.json').read_text())}
    cars = json.loads((data/'cars_0.json').read_text())
    signals = json.loads((data/'traffic_signals_0.json').read_text())
    layout = meta['layout']
    k = sum(1 for l in layout if l['role'] == 'connector')
    out.mkdir(parents=True, exist_ok=False)
    xs = [0.0]
    for l in layout: xs.append(xs[-1] + links[l['id']]['length'])
    signalled = {int(s['id'])-700: s['data']['content']['program']['stages'] for s in signals}
    nodes, edges, conns, tll = [], [], [], []
    for n, x in enumerate(xs):
        tl = n % 2 == 1 and ((n-1)//2) in signalled and n < len(xs)-1
        nodes.append(f'<node id="n{n}" x="{x:.4f}" y="0" type="{"traffic_light" if tl else "priority"}"/>')
    for n, l in enumerate(layout):
        edges.append(f'<edge id="e{l["id"]}" from="n{n}" to="n{n+1}" numLanes="2" speed="{EDGE_SPEED}" length="{links[l["id"]]["length"]:.4f}"/>')
    for n in range(len(layout)-1):
        a, b = layout[n], layout[n+1]
        tl_node = (n+1) % 2 == 1 and (((n+1)-1)//2) in signalled
        for lane in (0, 1):
            extra = f' tl="n{n+1}" linkIndex="{lane}"' if tl_node else ''
            conns.append(f'<connection from="e{a["id"]}" to="e{b["id"]}" fromLane="{lane}" toLane="{lane}"{extra}/>')
    for i, stages in sorted(signalled.items()):
        phases = []
        for st in stages:
            state = 'GG' if st['green'] else 'yy' if st['yellow'] else 'rr'
            phases.append(f'<phase duration="{st["durationSeconds"]:.3f}" state="{state}"/>')
        tll.append(f'<tlLogic id="n{2*i+1}" type="static" programID="0" offset="0">{"".join(phases)}</tlLogic>')
    (out/'net.nod.xml').write_text('<nodes>'+''.join(nodes)+'</nodes>')
    (out/'net.edg.xml').write_text('<edges>'+''.join(edges)+'</edges>')
    (out/'net.con.xml').write_text('<connections>'+''.join(conns)+'</connections>')
    (out/'net.tll.xml').write_text('<tlLogics>'+''.join(tll)+'</tlLogics>')
    subprocess.run(['netconvert', '-n', str(out/'net.nod.xml'), '-e', str(out/'net.edg.xml'), '-x', str(out/'net.con.xml'),
                    '-i', str(out/'net.tll.xml'), '-o', str(out/'net.net.xml'), '--no-turnarounds', 'true', '--no-warnings'], check=True, capture_output=True)
    order = [l['id'] for l in layout]
    vtypes, vehicles, clipped = [], [], []
    for car in sorted(cars, key=lambda c: (c['data']['content']['startTick'], c['id'])):
        c = car['data']['content']
        route_roads = [r['linkId'] for r in c['precomputedRoute']]
        first, last = order.index(route_roads[0]), order.index(route_roads[-1])
        edge_ids = ' '.join(f'e{order[j]}' for j in range(first, last+1))
        desired = c.get('microDesiredMaxSpeed')
        top = (desired if desired else LIMIT)
        depart_speed = c['microDepartSpeed']
        if depart_speed > top * 0.999:      # SUMO refuses insertion above the vehicle's own maximum speed (desired x edge limit)
            clipped.append(round(depart_speed - top, 3)); depart_speed = top * 0.999
        vt = f'v{car["id"]}'
        vtypes.append(f'<vType id="{vt}" vClass="passenger" carFollowModel="Krauss" length="{c["size"]:.4f}" minGap="2.5" accel="{c.get("microAcceleration", 2.6)}" decel="4.5" '
                      f'emergencyDecel="9.0" sigma="{sigma}" tau="1.0" speedFactor="{(desired if desired else LIMIT)/EDGE_SPEED:.5f}" speedDev="0" maxSpeed="40"/>')
        arrival = f' arrivalPos="{c["microArrivalPosition"]:.3f}"' if 'microArrivalPosition' in c else ''
        vehicles.append((c['startTick']*.1, f'<vehicle id="{car["id"]}" type="{vt}" depart="{c["startTick"]*.1:.1f}" departPos="{c["microDepartPosition"]:.3f}" '
                         f'departSpeed="{depart_speed:.3f}" departLane="{c["microDepartLane"]}"{arrival}><route edges="{edge_ids}"/></vehicle>'))
    vehicles.sort(key=lambda x: x[0])
    (out/'routes.rou.xml').write_text('<routes>'+''.join(vtypes)+''.join(v for _, v in vehicles)+'</routes>')
    (out/'clipped_departure_speeds.json').write_text(json.dumps(clipped))
    return meta, cars


def run(out, seed, end_s):
    subprocess.run(['sumo', '-n', str(out/'net.net.xml'), '-r', str(out/'routes.rou.xml'), '--fcd-output', str(out/'fcd.xml'), '--step-length', '0.1',
                    '--end', str(end_s), '--seed', str(seed), '--no-warnings', '--no-step-log', '--collision.action', 'warn', '--time-to-teleport', '-1'],
                   check=True, capture_output=True)


def events(out, order):
    """enter tick per (vehicle, edge) and first/last appearance, from the fcd output."""
    enter, seen, last_edge = {}, {}, {}
    for _, el in ET.iterparse(out/'fcd.xml', events=('end',)):
        if el.tag != 'timestep': continue
        t = round(float(el.get('time'))*10)
        for v in el.findall('vehicle'):
            vid, lane = int(v.get('id')), v.get('lane')
            # a vehicle on a junction-internal lane (':n<j>_...') has its front past node j, i.e. already on the next layout edge
            edge = order[int(lane[2:].split('_')[0])] if lane.startswith(':') else int(lane.split('_')[0][1:])
            seen.setdefault(vid, t)
            if last_edge.get(vid) != edge:
                enter[vid, edge] = t; last_edge[vid] = edge
        el.clear()
    return enter, seen


def analyze(scenario, out):
    meta = json.loads((scenario/'scenario_metadata.json').read_text())
    enter, seen = events(out, [l['id'] for l in meta['layout']])
    start, end = meta['start_frame'], meta['end_frame']
    direction, s_origin, s_sign, exit_end = meta.get('direction', '2'), meta.get('s_origin', 0.0), meta.get('s_sign', 1.0), meta['exit_end_m']
    subjects = {s['source_vehicle']: s for s in meta['subjects'] if s.get('category', 'through_only') == 'through_only'}
    observed = {}
    for source in meta['sources']:
        path = Path(source['path'])
        if hashlib.sha256(path.read_bytes()).hexdigest() != source['sha256']: raise ValueError('Raw source changed since generation')
        for row in json.loads(path.read_text()):
            vid, frame, s = int(row['vehicle_id']), int(row['frame_id']), s_origin + s_sign*float(row['local_y'])*FT
            if row['direction'] == direction and vid in subjects and subjects[vid]['first_frame'] <= frame <= end and s <= exit_end:
                observed.setdefault(vid, []).append((frame-start, s))
    raw_stop, raw_road = {i['name']: [] for i in meta['intersections']}, {}
    slips = {i['name']: [0, 0, 0] for i in meta['intersections']}
    delayed = 0
    for vid, subject in sorted(subjects.items()):
        native, obs = subject['native_vehicle'], observed.get(vid, [])
        first_s = obs[0][1] if obs else None
        if obs and native in seen and seen[native] - obs[0][0] > 10: delayed += 1
        for idx, inter in enumerate(meta['intersections']):
            connector = [l for l in meta['layout'] if l['role'] == 'connector' and l['intersection'] == idx][0]
            t_obs = next((t for t, s in obs if s >= inter['stop_bar_m']), None)
            if t_obs is not None and first_s is not None and first_s < inter['stop_bar_m'] and (native, connector['id']) in enter:
                e = (enter[native, connector['id']]-t_obs)*.1
                raw_stop[inter['name']].append([vid, round(e, 3)])
                slips[inter['name']][2] += 1; slips[inter['name']][0] += e > 20; slips[inter['name']][1] += abs(e) <= 5
        for idx, inter in enumerate(meta['intersections'][:-1]):
            nxt = meta['intersections'][idx+1]
            a = next((t for t, s in obs if s >= inter['box_end_m']), None)
            b = next((t for t, s in obs if s >= nxt['stop_bar_m']), None)
            road = [l for l in meta['layout'] if l['role'] == 'road' and l['intersection'] == idx+1][0]
            conn = [l for l in meta['layout'] if l['role'] == 'connector' and l['intersection'] == idx+1][0]
            if a is not None and b is not None and (native, road['id']) in enter and (native, conn['id']) in enter:
                raw_road.setdefault(nxt['name'], []).append([vid, round((b-a)*.1, 3), round((enter[native, conn['id']]-enter[native, road['id']])*.1, 3)])
    med = lambda v: round(statistics.median(v), 2) if v else None
    return dict(status='SUMO_REFERENCE', subjects=len(subjects), inserted=sum(1 for s in subjects.values() if s['native_vehicle'] in seen), inserted_more_than_10_ticks_late=delayed,
        stop_bar_crossing_error_s={k: dict(n=len(v), median=med([e for _, e in v])) for k, v in raw_stop.items()},
        stop_bar_slips={k: dict(model_one_cycle_later=v[0], within_5s=v[1], vehicles=v[2]) for k, v in slips.items()},
        raw=dict(stop_bar_error_s=raw_stop, road_time_s_observed_model=raw_road))


if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--scenario', type=Path, required=True)
    p.add_argument('--output', type=Path, required=True, help='new work directory for the SUMO files')
    p.add_argument('--sigma', type=float, default=0.0)
    p.add_argument('--seed', type=int, default=42)
    p.add_argument('--analysis', type=Path, required=True)
    a = p.parse_args()
    meta, _ = build(a.scenario, a.output, a.sigma)
    run(a.output, a.seed, meta['end_frame']-meta['start_frame'])
    result = analyze(a.scenario, a.output)
    result['sigma'], result['seed'] = a.sigma, a.seed
    clipped = json.loads((a.output/'clipped_departure_speeds.json').read_text())
    result['initial_speed_clipped_to_desired'] = dict(vehicles=len(clipped), max_m_s=max(clipped, default=0.0), median_m_s=statistics.median(clipped) if clipped else 0.0)
    with a.analysis.open('x') as f:
        json.dump(result, f, indent=2); f.write('\n')
    print(json.dumps({k: result[k] for k in result if k != 'raw'}, indent=1))
